<script setup lang="ts">
import {computed,ref,watch} from 'vue';
import {useEngineeringContext} from './useEngineeringProject';
import SeriesPreview from './SeriesPreview.vue';import SourceStudy from './SourceStudy.vue';import SourceAnalysis from './SourceAnalysis.vue';import ScenarioWorkspace from './ScenarioWorkspace.vue';import SequenceWorkspace from './SequenceWorkspace.vue';import NetworkView from './NetworkView.vue';import FaultPicker from './FaultPicker.vue';import PhaseEditor from './PhaseEditor.vue';import ParameterDialog from './ParameterDialog.vue';
import {inspectTimeSeries} from './timeSeries';
const {scene,project,customNetwork,networkParameters,params}=useEngineeringContext();
scene.ensure();const d=scene.draft;const backgroundMode=ref('current'),search=ref(''),records=ref<any[]>([]),libraryError=ref('');let request=0;
const selectedStage=ref(0);
const shownLines=computed(()=>(customNetwork.value?.lines||[]).filter((l:any)=>!search.value||String(l.line).includes(search.value)||String(l.name||'').includes(search.value)));
const activeFailures=computed<number[]>({get:()=>d.value?.faultTiming==='stages'?d.value.stages[selectedStage.value]?.failed_lines||[]:d.value?.failedLines||[],set:value=>{if(!d.value)return;if(d.value.faultTiming==='stages'){const stage=d.value.stages[selectedStage.value];if(stage)stage.failed_lines=value}else d.value.failedLines=value}});
function toggleLine(id:number){activeFailures.value=activeFailures.value.includes(id)?activeFailures.value.filter(v=>v!==id):[...activeFailures.value,id]}
async function importEvent(e:Event){const f=(e.target as HTMLInputElement).files?.[0];if(!f)return;try{const r=await fetch('/api/source-import/preview',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({text:await f.text(),filename:f.name})});const v=await r.json();if(!r.ok)throw Error(v.detail);scene.selectEvent(v.csv)}catch(error){scene.error.value=String(error)}}
function setCondition(){if(!d.value)return;d.value.conditionConfirmed=true;d.value.step='background';if(d.value.condition==='常规运行'){d.value.faultMode='none';d.value.eventMode='none';d.value.eventCsv='';scene.clearEmbedded()}}
watch(()=>scene.libraryOpen.value,async open=>{if(!open)return;const token=++request,id=project.value?.id;records.value=[];libraryError.value='';try{const [faults,sequences]=await Promise.all(['/api/scenarios?project_id=','/api/production-sequences?project_id='].map(async url=>{const r=await fetch(url+id);if(!r.ok)throw Error('读取历史场景失败');return r.json()}));if(token!==request||project.value?.id!==id)return;const details=await Promise.all(faults.map(async (s:any)=>{const response=await fetch('/api/scenarios/'+s.id);if(!response.ok)throw Error('历史场景详情读取失败');return {...await response.json(),kind:'fault'}}));if(token!==request||project.value?.id!==id)return;records.value=[...details,...sequences.map((s:any)=>({...s,kind:'sequence'}))]}catch(e){libraryError.value=String(e)}});
async function choose(record:any){try{if(record.kind==='fault')await scene.selectScenario(record.id);else await scene.selectProduction(record.csv,record.id,record.embedded_scenario_id);scene.libraryOpen.value=false}catch(e){libraryError.value=String(e)}}
function next(){const list=scene.steps.value;const index=list.findIndex(v=>v.id===d.value?.step);if(d.value)d.value.step=list[Math.min(index+1,list.length-1)].id}
function addStages(){if(!d.value)return;const hours=inspectTimeSeries(d.value.inputCsv).count;d.value.stages=[{name:'故障阶段',end_hour:Math.max(1,Math.floor(hours/2)),grid_ratio:1,emergency_ratio:1,failed_lines:[]},{name:'恢复阶段',end_hour:hours,grid_ratio:1,emergency_ratio:1,failed_lines:[]}];selectedStage.value=0}
</script>
<template><div v-if="d" class="scenario-settings"><p v-if="!d.conditionConfirmed" class="notice">旧工程未记录运行工况，请在顶部重新选择并确认；历史计算档案保持原记录。</p><p v-if="scene.stale.value" class="notice">上游数据或网架已变化，草稿待重新确认。<button @click="scene.reset">重新引用当前工程输入</button></p><p v-if="scene.error.value" class="notice" role="status">{{scene.error.value}}</p>
<nav class="scenario-steps" aria-label="场景配置步骤"><button v-for="(step,index) in scene.steps.value" :key="step.id" :class="{current:d.step===step.id}" @click="d.step=step.id">{{index+1}} {{step.label}}</button><span>{{scene.valid.value?'正式配置已应用':'配置草稿 · 尚未应用'}}</span></nav>
<template v-if="d.step==='background'"><article><div class="actions"><h3>背景时序</h3><label><input type="radio" v-model="backgroundMode" value="current">使用当前工程源荷</label><label><input type="radio" v-model="backgroundMode" value="generate">生成新的背景序列</label><button @click="scene.reset">重新引用当前工程</button></div><p>来源：{{d.source?.name||'当前工程源荷'}} · {{inspectTimeSeries(d.backgroundCsv).count}} 小时。无需重新生成已导入数据。</p><button v-if="!d.conditionConfirmed" @click="d.conditionConfirmed=true">确认顶部所选工况：{{d.condition}}</button><SeriesPreview v-if="backgroundMode==='current'" :csv="d.backgroundCsv"/></article><SourceStudy v-show="backgroundMode==='generate'" draft-mode :project-id="project?.id||''" :csv="d.backgroundCsv" :parameters="params" @apply="scene.selectBackground"/></template>
<template v-else-if="d.step==='event'"><article><h3>极端事件（可选）</h3><label class="field">设置方式<select v-model="d.eventMode"><option value="none">不额外设置源荷极端事件</option><option value="generate">生成极端源荷事件</option><option value="existing">载入已有极端事件</option></select></label><p>已有极端源荷可直接作为输入；未生成片段也可设置线路故障并进入确认。</p><template v-if="d.eventMode==='existing'"><label class="field">导入事件CSV<input type="file" accept=".csv" @change="importEvent"></label><SeriesPreview v-if="d.eventCsv" :csv="d.eventCsv"/><button v-if="d.eventCsv" @click="scene.selectEvent(d.eventCsv,true)">使用事件片段作为最终输入（不嵌入）</button></template></article><SourceAnalysis v-show="d.eventMode==='generate'" draft-mode :project-id="project?.id||''" :csv="d.backgroundCsv" @apply="v=>scene.selectEvent(v,true)" @window="v=>scene.selectEvent(v)"/></template>
<template v-else-if="d.step==='fault'"><article><h3>故障设置</h3><label class="field">故障方式<select v-model="d.faultMode"><option value="none">无设备故障</option><option value="manual">手动指定故障线路</option><option value="random">随机故障生成</option></select></label><p>三种方式互斥；随机资源容量场景与手动线路故障不会叠加。</p></article><div v-if="d.faultMode==='manual'" class="manual-fault-grid"><article><h3>当前真实网架 · 点击线路切换故障</h3><NetworkView v-if="customNetwork" :network="customNetwork" :placement="networkParameters" :failed-lines="activeFailures" editable @toggle-line="toggleLine"/><p v-else class="notice">尚未导入真实网架，请先到电网模型导入网架或明确载入示例。</p></article><article class="fault-controls"><h3>故障与恢复</h3><label class="field">时间方式<select v-model="d.faultTiming"><option value="full">全时域故障</option><option value="stages">指定阶段故障与恢复</option></select></label><p v-if="d.faultTiming==='stages'">阶段故障替代全时域故障，不重复叠加。结束小时采用左闭右开区间，恢复阶段清空故障线路。</p><template v-if="d.faultTiming==='stages'"><button v-if="!d.stages.length" @click="addStages">创建故障与恢复两阶段</button><label class="field">拓扑正在编辑阶段<select v-model.number="selectedStage"><option v-for="(s,i) in d.stages" :value="i">{{s.name}} · 至第{{s.end_hour}}小时</option></select></label></template><label class="field">搜索线路<input v-model="search" placeholder="真实支路编号或名称"></label><FaultPicker v-model="activeFailures" :lines="customNetwork?.lines||[]" :search="search"/><p v-for="id in activeFailures">线路 {{id}} · {{customNetwork?.lines.find((l:any)=>l.line===id)?.from_node}} → {{customNetwork?.lines.find((l:any)=>l.line===id)?.to_node}}</p><p class="notice">手动线路故障确认后使用节点网络模型；仅支持2–168小时。汇总模式不能忽略线路故障。</p></article></div><PhaseEditor v-if="d.faultMode==='manual'&&d.faultTiming==='stages'" v-model="d.stages" :disabled="false" network :lines="customNetwork?.lines||[]" :hours="inspectTimeSeries(d.inputCsv).count"/><ScenarioWorkspace v-if="d.faultMode==='random'" draft-mode :project-id="project?.id||''" :csv="d.eventCsv||d.inputCsv" :condition="d.condition" :event-csv="d.eventCsv" @apply="id=>scene.selectScenario(id).catch(e=>scene.error.value=String(e))"/></template>
<template v-else-if="d.step==='embed'"><article><h3>场景嵌入（可选）</h3><p>只需要手动故障或没有事件片段时可直接跳过，不会创建无意义序列。</p><button @click="if(d.productionId)scene.clearEmbedded();next()">跳过嵌入，使用当前所选输入</button></article><SequenceWorkspace v-if="d.eventCsv" draft-mode v-model="d.eventCsv" :project-id="project?.id||''" :csv="d.backgroundCsv" :parameters="params" @apply="(v,id,s)=>scene.selectProduction(v,id,s).catch(e=>scene.error.value=String(e))"/></template>
<article v-else-if="d.step==='confirm'" class="scenario-confirm"><h3>场景确认</h3><label class="field">场景名称<input v-model="d.name" maxlength="80"></label><dl><dt>运行工况</dt><dd>{{d.condition}}</dd><dt>背景来源</dt><dd>{{d.source?.name||'当前工程源荷'}}</dd><dt>计算范围</dt><dd>{{d.inputCsv.trim().split(/\r?\n/)[1]?.split(',')[0]}} — {{d.inputCsv.trim().split(/\r?\n/).slice(-1)[0]?.split(',')[0]}} · {{inspectTimeSeries(d.inputCsv).count}}小时</dd><dt>极端事件</dt><dd>{{d.eventMode==='none'?'不额外生成':d.eventCsv?'已选片段，'+inspectTimeSeries(d.eventCsv).count+'小时':'尚未选用'}}</dd><dt>故障方式</dt><dd>{{({none:'无设备故障',manual:'手动线路故障',random:'随机故障场景'})[d.faultMode]}}</dd><dt>故障线路/时间</dt><dd>{{d.faultMode==='manual'?(d.faultTiming==='full'?'全时域：'+d.failedLines.join('、'):d.stages.map(s=>s.name+'（至'+s.end_hour+'小时）：'+(s.failed_lines.join('、')||'无故障/恢复')).join('；')):'不施加手动线路故障'}}</dd><dt>生产序列</dt><dd>{{d.productionId||'未嵌入，使用所选源荷'}}</dd></dl><ul v-if="scene.issues.value.length" class="error"><li v-for="i in scene.issues.value"><button @click="d.step=i.step">{{i.message}}</button></li></ul><p v-else class="notice">配置完整性检查通过。确认只应用草稿并标记工程待保存，不提交平衡任务。</p><button class="primary" @click="scene.confirm">确认场景并进入平衡分析</button></article>
<div v-if="d.step!=='confirm'" class="step-actions"><span>当前步骤的生成结果只进入草稿</span><button @click="next">确认当前步骤，继续</button></div>
<ParameterDialog v-model:open="scene.libraryOpen.value" title="载入已有场景"><p v-if="libraryError" class="error">{{libraryError}}</p><p>以下为本工程实际历史产物。选择后只进入草稿，最终须在场景确认中应用。未记录的拓扑及工况保持未知。</p><div class="scroll"><table><tr><th>场景 / 来源</th><th>时间范围</th><th>拓扑 / 工况</th><th>操作</th></tr><tr v-for="r in records" :key="r.id"><td>{{r.name||r.id.slice(0,8)}} · {{r.kind==='fault'?'故障场景':'生产序列'}}<br>{{r.created}}</td><td>{{r.capacity?.[0]?.timestamp||r.rows?.[0]?.timestamp||'未记录'}} — {{r.capacity?.at(-1)?.timestamp||r.rows?.at(-1)?.timestamp||'未记录'}}</td><td>{{r.network?.name||'拓扑未记录'}} / {{r.operating_condition==='normal'?'常规运行':r.operating_condition==='extreme'?'极端保供':'工况未记录'}}</td><td><button @click="choose(r)">选入草稿</button></td></tr></table><p v-if="!records.length">当前工程没有已保存场景。</p></div></ParameterDialog></div></template>
<style scoped>.scenario-steps{display:flex;gap:8px;align-items:center;flex-wrap:wrap;margin-bottom:12px}.scenario-steps span{margin-left:auto;font-size:12px;color:#718096}.manual-fault-grid{display:grid;grid-template-columns:minmax(0,7fr) minmax(260px,3fr);gap:12px}.manual-fault-grid article{min-width:0}.step-actions{display:flex;justify-content:space-between;align-items:center;gap:12px;padding:12px 0}.step-actions span{font-size:12px;color:#718096}.scenario-confirm dl{display:grid;grid-template-columns:130px minmax(0,1fr);gap:12px}.scenario-confirm dd{margin:0;overflow-wrap:anywhere}.scenario-confirm dt{color:#718096}.fault-controls p{overflow-wrap:anywhere}@media(max-width:1050px){.manual-fault-grid{grid-template-columns:minmax(0,1fr)}.scenario-steps span{width:100%}}</style>
